static const size_t kModuleCount = sizeof(kModules) / sizeof(kModules[0]);

const EmbeddedModule *findEmbeddedModule(const char *id) {
  auto it = std::lower_bound(
      kModules, kModules + kModuleCount, id,
      [](const EmbeddedModule &m, const char *key) {
        return std::strcmp(m.id, key) < 0;
      });
  if (it != kModules + kModuleCount && std::strcmp(it->id, id) == 0)
    return it;
  return nullptr;
}

